// Configuração do cliente + validação do evento. O Chatlabs Trigger já entrega os campos normalizados.
const CFG = {
  company_id: 0,              // PREENCHER: companyId do cliente na Chatlabs
  departamento_humano_id: '', // PREENCHER: setor que recebe o transbordo para humano
  nome_ia: 'Ana',             // nome da atendente virtual
  nome_empresa: 'PREENCHER',  // nome da empresa como aparece para o cliente
  debounce_segundos: 10,      // espera para juntar mensagens seguidas antes de responder
  // Filtro de saída: únicos contatos/links que a IA pode citar.
  telefones_oficiais: [],     // só dígitos com DDD, ex.: '11999999999'
  hosts_oficiais: [],         // ex.: 'empresa.com.br'
  // Filtro de saída: ligue o que a BASE NÃO tem (se a IA citar, é invenção).
  bloquear_valores: true,     // R$, "reais", %
  bloquear_horarios: true,    // 14h, 14:30, 10/12
  bloquear_gratuidade: false, // "grátis", "sem custo" sem negação
  msg_bloqueio_entrada: 'Não consigo ajudar com esse tipo de pedido. Posso te ajudar com outra dúvida sobre nossos serviços?',
  msg_bloqueio_saida: 'Deixa eu confirmar essa informação com a nossa equipe. Já já uma pessoa continua com você por aqui.',
  msg_transferencia: 'Vou chamar alguém da nossa equipe para continuar com você, só um instante.',
};
const t = $input.first().json;
// Evento TRANSFER = o bot acabou de passar o chat para a IA. O texto é a opção do menu, não um pedido para a IA.
const entrada_menu = t.fromActionBlock === true || t.event === 'TRANSFER';
const out = {
  ...CFG,
  entrada_menu,
  companyId: t.companyId,
  chatId: t.chatId,
  attendantId: t.attendantId,
  clientName: t.clientName,
  clientPhone: t.clientPhone,
  message: String((entrada_menu && t.actionOption) || t.text || '').trim(),
  // Resposta de botão/lista do menu é texto para a IA.
  messageType: ['INTERACTIVE', 'BUTTON'].includes(t.messageType) ? 'TEXT' : t.messageType,
  fileUrl: t.fileUrl,
};
// Só segue se o evento é da empresa certa, tem chat e atendente de IA definido.
out.aceito = out.companyId === CFG.company_id && !!out.chatId && !!out.attendantId;
return [{ json: out }];

