// Só a execução da última mensagem do cliente segue; ela responde o bloco inteiro.
const rows = $input.all().map(i => i.json).filter(r => r && r.id).sort((a, b) => Number(a.id) - Number(b.id));
const meuId = Number($('INSERT.CHAT').first().json.id || 0);
const entradas = rows.filter(r => r.direction === 'incoming');
const ultimaEntrada = entradas.length ? Number(entradas[entradas.length - 1].id) : 0;
let ultSaida = -1;
rows.forEach((r, i) => { if (r.direction === 'outgoing') ultSaida = i; });
const bloco = rows.slice(ultSaida + 1).filter(r => r.direction === 'incoming')
  .map(r => String(r.conteudo || '').trim()).filter(Boolean).join('\n').slice(0, 3000);
const historico = rows.slice(0, ultSaida + 1).slice(-16)
  .map(r => (r.direction === 'incoming' ? 'Cliente: ' : 'Atendente: ') + String(r.conteudo || '').slice(0, 500))
  .join('\n');
return [{ json: {
  sou_a_ultima: meuId > 0 && meuId === ultimaEntrada,
  id_ultima_incoming: ultimaEntrada,
  primeira_conversa: !rows.some(r => r.direction === 'outgoing'),
  bloco,
  historico,
} }];

// Filtro de entrada: bloqueia tentativa de manipular a IA antes de gastar chamada de modelo.
// Regras fortes (peso >= 5) bloqueiam sozinhas; fracas só somadas na mesma categoria.
const original = String($json.bloco || '');
// Remove caracteres de controle e marcadores de papel que imitam o prompt.
const bloco_limpo = original
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u200B-\u200F\u202A-\u202E]/g, '')
  .replace(/<\|?\s*\/?\s*(system|developer|assistant|user)\s*\|?>|\[\/?(system|developer|assistant)\]|#{2,}\s*(system|developer)\b/gi, '')
  .trim();
const t = original.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ');
const regras = [
  ['PROMPT_INJECTION', 6, /\b(ignore|disregard|forget|bypass|override|ignorar|ignora|esqueca|esquece|desconsidere|substitua|contorne)\b.{0,55}\b(previous|prior|above|system|all|your|anteriores?|previas?|acima|sistema|internas?|todas?|suas?)\b.{0,40}\b(instructions?|rules|prompt|polic(y|ies)|instrucoes?|regras?|politicas?|ordens)\b/],
  ['PROMPT_INJECTION', 6, /\b(reveal|show|print|leak|repeat|tell me|revele|mostre|exiba|imprima|vaze|repita|me diga|me passe|me mostra)\b.{0,60}\b(system prompt|developer (message|prompt)|hidden prompt|internal (prompt|instructions)|prompt do sistema|prompt interno|seu prompt|suas instrucoes|instrucoes internas|regras internas)\b/],
  ['PROMPT_INJECTION', 6, /<\|?\s*(system|developer|assistant)\s*\|?>|\[(system|developer)\]|#{2,}\s*(system|developer)\b/],
  ['PROMPT_INJECTION', 5, /\b(jailbreak|do anything now|developer mode|god mode|modo desenvolvedor|modo (irrestrito|sem restricoes|sem filtro))\b/],
  ['PROMPT_INJECTION', 5, /\b(i am|i'm|sou|eu sou)\b.{0,25}\b(admin|administrador|developer|desenvolvedor|dona da empresa|dono da empresa|proprietari[oa]|gerente|root)\b.{0,60}\b(ignore|ignora|override|bypass|libere|libera|mostre|autorizo|desconto)\b/],
  ['PROMPT_INJECTION', 5, /\b(repeat|dump|repita|copie|mostre|retorne)\b.{0,45}\b(everything above|all text above|tudo acima|todo o contexto|contexto oculto|texto acima)\b/],
  ['PROMPT_INJECTION', 3, /\b(follow|obey|siga|obedeca)\b.{0,35}\b(following instructions|these instructions|instrucoes abaixo|seguintes instrucoes|novas instrucoes)\b/],
  ['PROMPT_INJECTION', 2, /\b(act as|pretend to be|you are now|finja que|aja como|agora voce e|a partir de agora voce)\b/],
  ['PROMPT_INJECTION', 3, /\b(base64|rot13|hexadecimal|decode|decodifique)\b/],
  ['SEGREDO', 6, /\b(show|reveal|print|send|give me|mostre|revele|envie|me passe|me manda|manda|qual (e|eh) a)\b.{0,55}\b(api[\s_-]?key|token|bearer|password|senha|secret|credencia(l|is)|chave privada|chave da api)\b/],
  ['SEGREDO', 5, /\b(process\.env|environment variables?|variaveis? de ambiente|\.env\b)\b/],
  ['SQL', 7, /\bunion\s+(all\s+)?select\b|;\s*(select|insert|update|delete|drop|alter|truncate)\b|\b(drop|truncate|alter)\s+(table|database|schema)\b|\b(information_schema|pg_catalog|pg_sleep)\b|\binsert\s+into\b|\bdelete\s+from\b/],
];
const hits = regras.filter(([, , re]) => re.test(t));
const porCategoria = {};
hits.forEach(([cat, peso]) => { porCategoria[cat] = (porCategoria[cat] || 0) + peso; });
const blocked = hits.some(([, peso]) => peso >= 5) || Object.values(porCategoria).some(v => v >= 5);
const motivo = blocked ? Object.entries(porCategoria).sort((a, b) => b[1] - a[1])[0][0] : 'SEGURO';
return [{ json: {
  ...$json,
  bloco_limpo,
  blocked,
  motivo,
  mensagem: blocked ? $('NORM').first().json.msg_bloqueio_entrada : '',
} }];

// Lê o JSON do agente. Se vier texto solto, trata como resposta normal.
const raw = String($json.output ?? '').trim();
let r = {};
try { r = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) { r = {}; }
const mensagem = String(r.mensagem || (r.acao ? '' : raw))
  .replace(/\s*[—–]\s*/g, ', ')
  .trim();
const transferir = r.acao === 'transferir';
return [{ json: {
  transferir,
  mensagem: mensagem || (transferir ? $('NORM').first().json.msg_transferencia : ''),
  resumo: String(r.resumo || '').trim(),
} }];

// Filtro de saída: nada que a IA escreveu sai sem passar por aqui.
// Se reprovar, o cliente recebe um aviso neutro e o chat vai para a equipe com o motivo na nota interna.
// Ligue/desligue as regras 1 a 3 no NORM conforme o que a BASE do cliente tem.
const cfg = $('NORM').first().json;
const MAX_CHARS = 1500;
const r = $json;
const msg = String(r.mensagem || '');
const t = msg.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const motivos = [];

// 1. Valor em reais ou percentual.
if (cfg.bloquear_valores) {
  for (const m of msg.matchAll(/R\$\s*\d[\d.,]*|\b\d[\d.]*(?:,\d{1,2})?\s*(?:reais|mil reais)\b/gi)) motivos.push('valor na resposta: ' + m[0].trim());
  for (const m of msg.matchAll(/(\d+(?:[.,]\d+)?)\s*%/g)) motivos.push('percentual na resposta: ' + m[0]);
}
// 2. Horário ou data. "15 dias" não casa aqui.
if (cfg.bloquear_horarios) {
  for (const m of msg.matchAll(/\b([01]?\d|2[0-3])\s*(?::\s*[0-5]\d|h(?:\s*[0-5]\d)?)(?![a-z0-9])/gi)) motivos.push('horário na resposta: ' + m[0].trim());
  for (const m of msg.matchAll(/\b(0?[1-9]|[12]\d|3[01])\s*\/\s*(0?[1-9]|1[0-2])(?:\s*\/\s*\d{2,4})?\b/g)) motivos.push('data na resposta: ' + m[0].trim());
}
// 3. Gratuidade sem negação na mesma frase.
if (cfg.bloquear_gratuidade) {
  for (const frase of t.split(/[.!?\n]+/)) {
    if (/\b(gratuit[oa]s?|gratis|de graca|sem custo|cortesia)\b/.test(frase) && !/\b(nao|nenhum[a]?|nunca)\b/.test(frase)) {
      motivos.push('menciona gratuidade: ' + frase.trim().slice(0, 80));
    }
  }
}
// 4. Placeholder de modelo de mensagem que não foi preenchido (ex.: [Data], [Endereço]).
for (const m of msg.matchAll(/\[[^\]\n]{2,40}\]/g)) motivos.push('texto entre colchetes: ' + m[0]);
// 5. E-mails, links e telefones: só os oficiais configurados no NORM.
const emails = msg.match(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/g) || [];
emails.forEach(e => motivos.push('e-mail não permitido: ' + e));
const semEmail = emails.reduce((acc, e) => acc.split(e).join(' '), msg);
for (const m of semEmail.matchAll(/(?:https?:\/\/|www\.)[^\s<>"']+|\b[a-z0-9-]+(?:\.[a-z0-9-]+)*\.(?:com|net|org|io|me|ly|app|link|xyz|site|store|shop|info)(?:\.br)?\b[^\s<>"']*/gi)) {
  const url = m[0].replace(/[),.;!?]+$/, '');
  const host = url.replace(/^https?:\/\//i, '').split(/[\/?#]/)[0].toLowerCase().replace(/^www\./, '');
  const ok = (cfg.hosts_oficiais || []).some(h => host === h || host.endsWith('.' + h));
  if (!ok) motivos.push('link não permitido: ' + url);
}
for (const m of semEmail.matchAll(/(?<!\d)(?:\+?55[\s-]?)?\(?\d{2}\)?[\s-]?9?[\s.-]?\d{4}[\s.-]?\d{4}(?!\d)/g)) {
  const dig = m[0].replace(/\D/g, '').replace(/^55(?=\d{10,11}$)/, '');
  if (!(cfg.telefones_oficiais || []).includes(dig)) motivos.push('telefone não oficial: ' + m[0].trim());
}
// 6. Vazamento de instruções ou de que é um modelo.
if (/\bprompt\b|system message|instruc(ao|oes) (interna|do sistema)|base de conhecimento|formato da resposta|mensagens_cliente|"acao"|\bopenai\b|chat ?gpt|\bgpt\b|modelo de linguagem|inteligencia artificial|\bsou (uma |um )?(ia|robo|bot)\b/.test(t)) {
  motivos.push('possível vazamento de instruções');
}
// 7. Tamanho.
if (msg.length > MAX_CHARS) motivos.push('resposta longa demais (' + msg.length + ' caracteres)');

const aprovado = motivos.length === 0;
return [{ json: {
  aprovado,
  motivos,
  transferir: aprovado ? r.transferir : true,
  mensagem: aprovado ? msg : cfg.msg_bloqueio_saida,
  resumo: aprovado ? r.resumo
    : 'Resposta da IA barrada pelo filtro de saída (' + motivos.join('; ') + '). ' + (r.resumo ? 'Resumo: ' + r.resumo + '. ' : '')
      + 'Texto barrado: ' + msg.slice(0, 500),
} }];
